/* NOIR portfolio preview embedded as data URIs: the GitHub connector can only push
   text files, so the binary preview (assets/previews/noir.mp4 and noir.jpg, kept in
   the local workspace) travels inside this text file. app.js prefers these values
   and falls back to the plain preview paths if this file is missing. */
window.NOIR_PREVIEW_VIDEO = "data:video/mp4;base64,";
window.NOIR_PREVIEW_POSTER = "data:image/jpeg;base64,";
